import sys
input = sys.stdin.readline

def z_function(s):
    n = len(s)
    z = [0] * n
    z[0] = n
    l = rr = 0
    for i in range(1, n):
        if i < rr:
            z[i] = min(rr - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > rr:
            l, rr = i, i + z[i]
    return z

t = input().strip()
p = input().strip()

n = len(t)
m = len(p)
if m > n:
    print(0)
else:
    zf = z_function(p + '#' + t)
    zr = z_function(p[::-1] + '#' + t[::-1])
    count = 0
    for i in range(n - m + 1):
        if zf[m + 1 + i] + zr[n + 1 - i] >= m - 1:
            count += 1
    print(count)

