#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> zFunction(const string& s) {
    int n = (int)s.size();
    vector<int> z(n, 0);
    z[0] = n;
    int l = 0, rr = 0;
    for (int i = 1; i < n; i++) {
        if (i < rr) z[i] = min(rr - i, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > rr) {
            l = i;
            rr = i + z[i];
        }
    }
    return z;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string t;
    cin >> t;
    string p;
    cin >> p;

    int n = (int)t.size(), m = (int)p.size();
    if (m > n) {
        cout << 0 << "\n";
    } else {
        string rp(p.rbegin(), p.rend()), rt(t.rbegin(), t.rend());
        vector<int> zf = zFunction(p + "#" + t);
        vector<int> zr = zFunction(rp + "#" + rt);
        long long count = 0;
        for (int i = 0; i + m <= n; i++) {
            if (zf[m + 1 + i] + zr[n + 1 - i] >= m - 1) count++;
        }
        cout << count << "\n";
    }

    return 0;
}

