import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] zFunction(String s) {
        int n = s.length();
        int[] z = new int[n];
        z[0] = n;
        int l = 0, rr = 0;
        for (int i = 1; i < n; i++) {
            if (i < rr) z[i] = Math.min(rr - i, z[i - l]);
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] > rr) {
                l = i;
                rr = i + z[i];
            }
        }
        return z;
    }

    public static void main(String[] args) throws IOException {
        String t = next();
        String p = next();

        int n = t.length(), m = p.length();
        if (m > n) {
            System.out.println(0);
        } else {
            String rp = new StringBuilder(p).reverse().toString();
            String rt = new StringBuilder(t).reverse().toString();
            int[] zf = zFunction(p + "#" + t);
            int[] zr = zFunction(rp + "#" + rt);
            long count = 0;
            for (int i = 0; i + m <= n; i++) {
                if (zf[m + 1 + i] + zr[n + 1 - i] >= m - 1) count++;
            }
            System.out.println(count);
        }
    }
}
